import type { AffiliateLinkSource, CatalogProduct } from '../../types/product';
import type { AffiliateProductProvider, ProviderCallContext } from '../providers/types';

/**
 * Resolves the outbound link for each result:
 *  1. official link supplied by the provider (feed `aw_deep_link`, API `promotion_link`);
 *  2. a link generated by the provider's official link API (cached);
 *  3. otherwise the plain, non-affiliate product page;
 *  4. demo items have no destination at all.
 * Nothing is ever fabricated: if the provider can't produce a tracking link,
 * the item is linked without tracking and marked `isAffiliate: false`.
 */
export interface ResolvedLink {
  destination: string | null;
  isAffiliate: boolean;
  source: AffiliateLinkSource | 'plain' | 'demo';
}

export interface AffiliateLinkCache {
  get(provider: string, ids: string[]): Promise<Map<string, string>>;
  set(provider: string, rows: { id: string; destination: string; affiliateUrl: string; source: AffiliateLinkSource }[]): Promise<void>;
}

export class MemoryLinkCache implements AffiliateLinkCache {
  private readonly map = new Map<string, { url: string; expires: number }>();
  constructor(private readonly ttlMs = 30 * 86400_000) {}
  async get(provider: string, ids: string[]) {
    const out = new Map<string, string>();
    const now = Date.now();
    for (const id of ids) {
      const e = this.map.get(`${provider}:${id}`);
      if (e && e.expires > now) out.set(id, e.url);
    }
    return out;
  }
  async set(provider: string, rows: { id: string; affiliateUrl: string }[]) {
    if (this.map.size > 20_000) this.map.clear();
    for (const r of rows) this.map.set(`${provider}:${r.id}`, { url: r.affiliateUrl, expires: Date.now() + this.ttlMs });
  }
}

export class AffiliateLinkService {
  constructor(private readonly cache: AffiliateLinkCache) {}

  async resolve(products: CatalogProduct[], provider: AffiliateProductProvider, ctx?: ProviderCallContext): Promise<Map<string, ResolvedLink>> {
    const out = new Map<string, ResolvedLink>();
    const needGeneration: CatalogProduct[] = [];
    for (const p of products) {
      if (p.isDemo) out.set(p.providerProductId, { destination: null, isAffiliate: false, source: 'demo' });
      else if (p.affiliateUrl) out.set(p.providerProductId, { destination: p.affiliateUrl, isAffiliate: true, source: p.affiliateSource ?? 'api' });
      else needGeneration.push(p);
    }
    if (needGeneration.length) {
      const cached = await this.cache.get(provider.id, needGeneration.map((p) => p.providerProductId)).catch(() => new Map<string, string>());
      const missing = needGeneration.filter((p) => !cached.has(p.providerProductId));
      let generated = new Map<string, string>();
      if (missing.length && provider.generateAffiliateLinks) {
        generated = await provider.generateAffiliateLinks(missing, ctx).catch(() => new Map<string, string>());
        if (generated.size) {
          await this.cache
            .set(
              provider.id,
              [...generated].map(([id, url]) => ({
                id,
                destination: missing.find((m) => m.providerProductId === id)?.productUrl ?? '',
                affiliateUrl: url,
                source: provider.id === 'awin' ? ('deeplink' as const) : ('api' as const),
              })),
            )
            .catch(() => undefined);
        }
      }
      for (const p of needGeneration) {
        const link = cached.get(p.providerProductId) ?? generated.get(p.providerProductId);
        if (link) out.set(p.providerProductId, { destination: link, isAffiliate: true, source: provider.id === 'awin' ? 'deeplink' : 'api' });
        else out.set(p.providerProductId, { destination: p.productUrl, isAffiliate: false, source: 'plain' });
      }
    }
    return out;
  }
}
